#include <iostream>
#include <vector>
using namespace std;

int countDistinctValues(int k, int m) {
    // visited[x] 表示值 x 是否已经出现过
    vector<bool> visited(m, false);

    // 初始值 a = 1
    int a = 1;
    int ans = 0;

    // 当当前值没有出现过时，继续模拟
    while (!visited[a]) {
        // 标记当前值已出现
        visited[a] = true;

        // 不同值个数加一
        ans++;

        // 按题意更新 a
        // 这里使用 long long，避免乘法过程中的整型风险
        a = (int)((1LL * a * k) % m);
    }

    return ans;
}

int main() {
    // 读取输入
    int k, m;
    cin >> k >> m;

    // 调用函数并输出答案
    cout << countDistinctValues(k, m) << '\n';

    return 0;
}
